def robust(a, b):
    m = np.linalg.lstsq(a, b, rcond=None)[0]
    for scale in [0.3, 0.1, 0.03, 0.01, 0.003, 0.001]:
        for _ in range(15):
            r = np.linalg.norm(a @ m - b, axis=1)
            w = 1 / np.hypot(1, r / scale)
            m = np.linalg.lstsq(a * w[:, None], b * w[:, None], rcond=None)[0]
    return m

def sat(z, k, kind):
    if kind == 'rat':
        return z / (1 + k * z * z)
    if kind == 'root':
        return z / np.sqrt(1 + k * z * z)
    if kind == 'tanh':
        return np.tanh(z * np.sqrt(k)) / np.sqrt(k)
    if kind == 'atan':
        return np.arctan(z * np.sqrt(k)) / np.sqrt(k)
    if kind == 'exp':
        return z * np.exp(-k * z * z)

def fit(x, y, kind, layout):
    from scipy.optimize import least_squares
    af = lambda z: np.column_stack((np.ones(len(z)), z))
    a = af(x)
    base = robust(a, y)
    e = np.linalg.norm(a @ base - y, axis=1)
    good = e < max(2, 4 * np.median(e))
    if layout in ('pre', 'preplus', 'prequad'):

        def des(z, k):
            q = sat(z, k, kind)
            return af(q) if layout == 'pre' else np.column_stack((af(q), z) if layout == 'preplus' else (af(q), z, z * z))
        p = np.full(4, 0.7)
        for _ in range(3):

            def err(k):
                a = des(x[good], k)
                return (a @ lin(a, y[good]) - y[good]).ravel()
            p = least_squares(err, p, bounds=(0.003, 15), max_nfev=100).x
            a = des(x, p)
            m = lin(a[good], y[good])
            e = np.linalg.norm(a @ m - y, axis=1)
            good = e < max(0.025, 5 * np.median(e))
        return (lambda z: des(z, p) @ m, p, m)
    p = np.r_[base[0], (base[1:] / np.diag(base[1:]))[~np.eye(4, dtype=bool)], np.diag(base[1:]), np.full(4, 0.7), np.full(4, 0.0) if layout == 'postplus' else []]

    def pred(z, p):
        mix = np.eye(4)
        mix[~np.eye(4, dtype=bool)] = p[4:16]
        h = z @ mix
        return p[:4] + p[16:20] * sat(h, p[20:24], kind) + (p[24:28] * h if layout == 'postplus' else 0)
    for _ in range(3):
        b = np.full(len(p), np.inf)
        low = -b.copy()
        low[20:24] = 0.003
        b[20:24] = 15
        p = least_squares(lambda p: (pred(x[good], p) - y[good]).ravel(), p, bounds=(low, b), max_nfev=120).x
        e = np.linalg.norm(pred(x, p) - y, axis=1)
        good = e < max(0.025, 5 * np.median(e))
    return (lambda z: pred(z, p), p, None)
